import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Quick Start Guide","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/quick-start.md","filePath":"get-started/quick-start.md"}'),s={name:"get-started/quick-start.md"};function i(n,t,l,d,c,h){return a(),r("div",null,t[0]||(t[0]=[o('<h1 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h1><p>This guide will get you translating in under 5 minutes.</p><p>If you&#39;re not sure where to begin: import a file, translate a few segments, then export back to your CAT tool.</p><h2 id="step-1-start-supervertaler" tabindex="-1">Step 1: Start Supervertaler <a class="header-anchor" href="#step-1-start-supervertaler" aria-label="Permalink to &quot;Step 1: Start Supervertaler&quot;">​</a></h2><p>Launch the application by running <code>Supervertaler.exe</code> (Windows) or <code>python Supervertaler.py</code> (from source).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you want to use AI translation, set up your API keys first: <a href="./api-keys.html">Setting Up API Keys</a>.</p></div><h2 id="step-2-import-a-document" tabindex="-1">Step 2: Import a Document <a class="header-anchor" href="#step-2-import-a-document" aria-label="Permalink to &quot;Step 2: Import a Document&quot;">​</a></h2><ol><li>Go to <strong>File → Import</strong></li><li>Choose your file type: <ul><li><strong>DOCX</strong> - Standard Word documents</li><li><strong>Text File</strong> - Plain text (one segment per line)</li><li><strong>memoQ Bilingual</strong> - memoQ XLIFF or bilingual DOCX</li><li><strong>Trados Package</strong> - SDLPPX files</li><li><strong>Phrase Bilingual</strong> - Memsource bilingual DOCX</li><li><strong>CafeTran Bilingual</strong> - CafeTran external view</li></ul></li><li>Select source and target languages when prompted</li><li>Your document appears in the translation grid</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you&#39;re working with memoQ/Trados/Phrase/CafeTran, always choose the matching import option so tags and statuses round-trip correctly.</p></div><h2 id="step-3-navigate-the-grid" tabindex="-1">Step 3: Navigate the Grid <a class="header-anchor" href="#step-3-navigate-the-grid" aria-label="Permalink to &quot;Step 3: Navigate the Grid&quot;">​</a></h2><p>The translation grid has 4 columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>#</strong></td><td>Segment number</td></tr><tr><td><strong>Status</strong></td><td>Translation status indicator</td></tr><tr><td><strong>Source</strong></td><td>Original text (read-only)</td></tr><tr><td><strong>Target</strong></td><td>Your translation (editable)</td></tr></tbody></table><h3 id="basic-navigation" tabindex="-1">Basic Navigation <a class="header-anchor" href="#basic-navigation" aria-label="Permalink to &quot;Basic Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Next segment</td><td><code>Enter</code> or <code>↓</code> (at end of cell)</td></tr><tr><td>Previous segment</td><td><code>↑</code> (at start of cell)</td></tr><tr><td>Go to segment</td><td><code>Ctrl+G</code></td></tr></tbody></table><p>Most navigation is designed to feel memoQ-like: arrow keys move within a cell, and at the top/bottom line they can jump between segments.</p><h2 id="step-4-translate-a-segment" tabindex="-1">Step 4: Translate a Segment <a class="header-anchor" href="#step-4-translate-a-segment" aria-label="Permalink to &quot;Step 4: Translate a Segment&quot;">​</a></h2><h3 id="manual-translation" tabindex="-1">Manual Translation <a class="header-anchor" href="#manual-translation" aria-label="Permalink to &quot;Manual Translation&quot;">​</a></h3><ol><li>Click in the <strong>Target</strong> cell</li><li>Type your translation</li><li>Confirm the segment (confirmed statuses matter when exporting back to CAT tools)</li></ol><h3 id="ai-translation" tabindex="-1">AI Translation <a class="header-anchor" href="#ai-translation" aria-label="Permalink to &quot;AI Translation&quot;">​</a></h3><ol><li>Select a segment</li><li>Use the <strong>Translate action</strong> (single segment; <strong>Ctrl+T</strong>) or <strong>Batch Translate</strong> (multiple segments)</li><li>Review and edit if needed</li><li>Confirm the segment when you&#39;re happy</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If AI translation isn&#39;t available yet, double-check provider setup in <a href="./api-keys.html">Setting Up API Keys</a>.</p></div><h2 id="step-5-save-your-project" tabindex="-1">Step 5: Save Your Project <a class="header-anchor" href="#step-5-save-your-project" aria-label="Permalink to &quot;Step 5: Save Your Project&quot;">​</a></h2><ol><li>Press <code>Ctrl+S</code> or go to <strong>File → Save Project</strong></li><li>Choose a location and filename</li><li>Projects are saved as <code>.svproj</code> files</li></ol><h2 id="step-6-export-your-translation" tabindex="-1">Step 6: Export Your Translation <a class="header-anchor" href="#step-6-export-your-translation" aria-label="Permalink to &quot;Step 6: Export Your Translation&quot;">​</a></h2><ol><li>Go to <strong>File → Export</strong></li><li>Choose the appropriate format: <ul><li><strong>DOCX</strong> - Translated Word document</li><li><strong>Bilingual Table</strong> - Side-by-side source/target</li><li><strong>Return Package</strong> - For CAT tool workflows</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>For CAT tool workflows, always export the matching return format (for example, SDLRPX for Trados return packages) to preserve tags and statuses.</p></div><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><h3 id="recommended-next-steps" tabindex="-1">Recommended next steps <a class="header-anchor" href="#recommended-next-steps" aria-label="Permalink to &quot;Recommended next steps&quot;">​</a></h3><ul><li><a href="./api-keys.html">Setting Up API Keys</a> — enable AI translation</li><li><a href="./installation.html">Installation</a> — verify dependencies and optional components</li><li><a href="./../cat-tools/overview.html">CAT Tool Integration</a> — memoQ/Trados/Phrase/CafeTran workflows</li><li><a href="./../editor/keyboard-shortcuts.html">Keyboard Shortcuts</a> — faster editing and navigation</li></ul><div class="sv-cards"><a class="sv-card" href="/get-started/api-keys"><span class="sv-card-title">Set up AI Translation</span><span class="sv-card-desc">Configure API keys →</span></a><a class="sv-card" href="/editor/keyboard-shortcuts"><span class="sv-card-title">Learn Keyboard Shortcuts</span><span class="sv-card-desc">View all shortcuts →</span></a><a class="sv-card" href="/cat-tools/overview"><span class="sv-card-title">Work with CAT Tools</span><span class="sv-card-desc">CAT tool integration →</span></a></div>',31)]))}const g=e(s,[["render",i]]);export{u as __pageData,g as default};
